def evaluate(expr: str) -> float:
    """Evaluate an arithmetic expression with + - * /, parentheses and unary minus."""

    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    # ---------- tokenizer ----------
    def tokenize(s):
        tokens = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c.isspace():
                i += 1
                continue
            if c in '+-*/()':
                tokens.append(c)
                i += 1
                continue
            if c.isdigit() or c == '.':
                j = i
                dots = 0
                digits = 0
                while j < n and (s[j].isdigit() or s[j] == '.'):
                    if s[j] == '.':
                        dots += 1
                    else:
                        digits += 1
                    j += 1
                if dots > 1 or digits == 0:
                    raise ValueError("malformed number: %r" % s[i:j])
                tokens.append(float(s[i:j]))
                i = j
                continue
            raise ValueError("unknown character: %r" % c)
        return tokens

    tokens = tokenize(expr)
    if not tokens:
        raise ValueError("empty expression")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    # ---------- recursive descent parser ----------
    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs
        return value

    def parse_factor():
        tok = peek()
        if tok == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        if isinstance(tok, float):
            advance()
            return tok
        if tok == '(':
            advance()
            value = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            advance()
            return value
        raise ValueError("unexpected token: %r" % (tok,))

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected token: %r" % (tokens[pos],))
    return float(result)
